head.script:
scwin.findElementBySuffix = function(suffix) {
    var nodes = document.querySelectorAll("[id$='" + suffix + "']");
    return nodes.length > 0 ? nodes[0] : null;
};

scwin.runDropProbe = function() {
    var tbody = scwin.findElementBySuffix("multiupload1_tbody");
    var result = {
        rowCount: 0,
        fileCount: 0,
        checked: false,
        selected: false
    };

    multiupload1.html5Upload = true;
    multiupload1.options.mode = "html5";
    multiupload1.dom.tbody = tbody;
    multiupload1.fileArray = [];
    multiupload1.fileNameArr = [];
    multiupload1._inx = 0;
    if (tbody) {
        tbody.innerHTML = "";
    }

    multiupload1._handleOndrop({
        preventDefault: function() {},
        stopPropagation: function() {},
        dataTransfer: {
            files: [
                { name: "WAEA_909_drop_a.txt", size: 10 },
                { name: "WAEA_909_drop_b.txt", size: 20 }
            ]
        }
    });

    if (tbody) {
        var rows = tbody.querySelectorAll("tr");
        result.rowCount = rows.length;
        if (rows.length > 0) {
            rows[0].click();
            var checkbox = rows[0].querySelector("input[type='checkbox']");
            result.checked = checkbox ? checkbox.checked : false;
            result.selected = rows[0].classList.contains("w2multiupload_html5_uploader_selected");
        }
    }
    result.fileCount = multiupload1.fileNameArr.length;
    txtResult.setValue(
        result.fileCount === 2 && result.rowCount === 2 && result.checked && result.selected ? "PASS" : "FAIL"
    );
    txtDetail.setValue(JSON.stringify(result));
};

scwin.onpageload = function() {
    setTimeout(scwin.runDropProbe, 300);
};
